export type Recipient = Readonly<{
  name: string;
  postalAddress: string;
}>;

export type ProviderRequest = Readonly<{
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}>;

export type ShippingDependencies = Readonly<{
  repository: Readonly<{
    get: (shipmentId: string) => Promise<unknown>;
    save: (shipmentId: string, record: unknown) => Promise<void>;
  }>;
  atlas: Readonly<{
    book: (request: ProviderRequest) => Promise<unknown>;
  }>;
  beacon: Readonly<{
    reserve: (request: ProviderRequest) => Promise<unknown>;
  }>;
  logger: Readonly<{
    info: (event: Record<string, unknown>) => void;
  }>;
}>;

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";

type Rejection = Readonly<{
  provider: Provider;
  reason: RefusalReason;
}>;

type ShipmentFields = Readonly<{
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}>;

type QueuedShipment = ShipmentFields &
  Readonly<{
    state: "queued";
  }>;

type DispatchedShipment = ShipmentFields &
  Readonly<{
    state: "dispatched";
    provider: Provider;
    bookingId: string;
    dispatchedAtMs: number;
  }>;

type DeferredShipment = ShipmentFields &
  Readonly<{
    state: "deferred";
    nextProvider: Provider;
    retryAtMs: number;
    rejections: readonly Rejection[];
  }>;

type UnavailableShipment = ShipmentFields &
  Readonly<{
    state: "unavailable";
    rejections: readonly Rejection[];
  }>;

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

type AbortBody = Readonly<{
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: Provider | "repository";
  classification:
    | "unknown_failure"
    | "invalid_provider_response"
    | "repository_failure";
  rejections: readonly Rejection[];
}>;

export type ServiceResponse = Readonly<{
  status: number;
  body:
    | PublicShipment
    | AbortBody
    | {
        code: "invalid_command" | "not_found";
      };
}>;

type Command =
  | Readonly<{ op: "get"; shipmentId: string }>
  | Readonly<{
      op: "dispatch";
      shipmentId: string;
      nowMs: number;
      recipient: Recipient;
    }>;

type Confirmation = Readonly<{
  provider: Provider;
  bookingId: string;
}>;

type CarrierOutcome =
  | Readonly<{ kind: "confirmed"; confirmation: Confirmation }>
  | Readonly<{ kind: "refused"; rejection: Rejection }>
  | Readonly<{ kind: "throttled"; retryAtMs: number }>
  | Readonly<{
      kind: "aborted";
      classification: "unknown_failure" | "invalid_provider_response";
    }>;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isNonemptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isNonblankString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function isSafeNonnegativeInteger(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value >= 0
  );
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function isRejection(value: unknown): value is Rejection {
  return (
    isObject(value) &&
    isProvider(value.provider) &&
    isRefusalReason(value.reason)
  );
}

function areRejections(value: unknown): value is readonly Rejection[] {
  return Array.isArray(value) && value.every(isRejection);
}

function parseCommand(value: unknown): Command | undefined {
  if (
    !isObject(value) ||
    typeof value.shipmentId !== "string" ||
    value.shipmentId.length === 0
  ) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    !isSafeNonnegativeInteger(value.nowMs) ||
    !isObject(value.recipient) ||
    !isNonblankString(value.recipient.name) ||
    !isNonblankString(value.recipient.postalAddress)
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function hasShipmentFields(
  value: Record<string, unknown>,
): value is Record<string, unknown> & ShipmentFields {
  return (
    value.schemaVersion === 1 &&
    typeof value.id === "string" &&
    typeof value.routeCode === "string" &&
    Number.isSafeInteger(value.parcelGrams)
  );
}

function parseStoredShipment(value: unknown): StoredShipment | undefined {
  if (!isObject(value) || !hasShipmentFields(value)) {
    return undefined;
  }
  const fields = {
    schemaVersion: 1,
    id: value.id,
    routeCode: value.routeCode,
    parcelGrams: value.parcelGrams,
  } as const;

  if (value.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    isNonemptyString(value.bookingId) &&
    isSafeNonnegativeInteger(value.dispatchedAtMs)
  ) {
    return {
      ...fields,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }
  if (
    value.state === "deferred" &&
    isProvider(value.nextProvider) &&
    isSafeNonnegativeInteger(value.retryAtMs) &&
    areRejections(value.rejections)
  ) {
    return {
      ...fields,
      state: "deferred",
      nextProvider: value.nextProvider,
      retryAtMs: value.retryAtMs,
      rejections: [...value.rejections],
    };
  }
  if (value.state === "unavailable" && areRejections(value.rejections)) {
    return {
      ...fields,
      state: "unavailable",
      rejections: [...value.rejections],
    };
  }
  return undefined;
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
  switch (shipment.state) {
    case "queued":
      return { ...fields, state: "queued" };
    case "dispatched":
      return {
        ...fields,
        state: "dispatched",
        provider: shipment.provider,
        bookingId: shipment.bookingId,
        dispatchedAtMs: shipment.dispatchedAtMs,
      };
    case "deferred":
      return {
        ...fields,
        state: "deferred",
        nextProvider: shipment.nextProvider,
        retryAtMs: shipment.retryAtMs,
        rejections: [...shipment.rejections],
      };
    case "unavailable":
      return {
        ...fields,
        state: "unavailable",
        rejections: [...shipment.rejections],
      };
  }
}

function abortBody(
  shipmentId: string,
  failedAt: Provider | "repository",
  classification: AbortBody["classification"],
  rejections: readonly Rejection[],
): AbortBody {
  return {
    code: "dispatch_aborted",
    shipmentId,
    failedAt,
    classification,
    rejections: [...rejections],
  };
}

function emitAbort(
  dependencies: ShippingDependencies,
  body: AbortBody,
): ServiceResponse {
  dependencies.logger.info({
    shipmentId: body.shipmentId,
    action: "aborted",
    failedAt: body.failedAt,
    classification: body.classification,
    rejections: [...body.rejections],
  });
  return { status: 500, body };
}

function providerRequest(
  shipment: StoredShipment,
  recipient: Recipient,
): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function parseAtlasRejection(value: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(value)) {
    return { kind: "aborted", classification: "unknown_failure" };
  }
  if (value.code === "cannot_ship") {
    if (isRefusalReason(value.reason)) {
      return {
        kind: "refused",
        rejection: { provider: "atlas", reason: value.reason },
      };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (value.code === "rate_limited") {
    if (
      typeof value.retryAtMs === "number" &&
      Number.isSafeInteger(value.retryAtMs) &&
      value.retryAtMs > nowMs
    ) {
      return { kind: "throttled", retryAtMs: value.retryAtMs };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", classification: "unknown_failure" };
}

function parseBeaconRejection(value: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(value)) {
    return { kind: "aborted", classification: "unknown_failure" };
  }
  if (value.type === "rejected") {
    if (isObject(value.details) && isRefusalReason(value.details.reason)) {
      return {
        kind: "refused",
        rejection: { provider: "beacon", reason: value.details.reason },
      };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (value.type === "throttled") {
    if (
      isObject(value.details) &&
      typeof value.details.retryAtMs === "number" &&
      Number.isSafeInteger(value.details.retryAtMs) &&
      value.details.retryAtMs > nowMs
    ) {
      return { kind: "throttled", retryAtMs: value.details.retryAtMs };
    }
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", classification: "unknown_failure" };
}

function parseConfirmation(
  provider: Provider,
  confirmation: unknown,
): CarrierOutcome {
  if (!isObject(confirmation)) {
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (provider === "atlas" && isNonemptyString(confirmation.bookingId)) {
    return {
      kind: "confirmed",
      confirmation: { provider, bookingId: confirmation.bookingId },
    };
  }
  if (provider === "beacon" && isNonemptyString(confirmation.reference)) {
    return {
      kind: "confirmed",
      confirmation: { provider, bookingId: confirmation.reference },
    };
  }
  return { kind: "aborted", classification: "invalid_provider_response" };
}

async function callCarrier(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
): Promise<CarrierOutcome> {
  try {
    const confirmation =
      provider === "atlas"
        ? await dependencies.atlas.book(request)
        : await dependencies.beacon.reserve(request);
    return parseConfirmation(provider, confirmation);
  } catch (error) {
    return provider === "atlas"
      ? parseAtlasRejection(error, nowMs)
      : parseBeaconRejection(error, nowMs);
  }
}

function baseShipment(shipment: StoredShipment): ShipmentFields {
  return {
    schemaVersion: 1,
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
}

async function saveDecision(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  record: StoredShipment,
  event: Record<string, unknown>,
  repositoryFailureRejections: readonly Rejection[],
): Promise<ServiceResponse> {
  try {
    await dependencies.repository.save(shipment.id, record);
  } catch {
    return emitAbort(
      dependencies,
      abortBody(
        shipment.id,
        "repository",
        "repository_failure",
        repositoryFailureRejections,
      ),
    );
  }
  dependencies.logger.info(event);
  const status =
    record.state === "deferred" ? 202 : record.state === "unavailable" ? 422 : 200;
  return { status, body: publicShipment(record) };
}

function hasPermanentRefusal(
  rejections: readonly Rejection[],
  provider: Provider,
): boolean {
  return rejections.some((rejection) => rejection.provider === provider);
}

async function dispatchShipment(
  dependencies: ShippingDependencies,
  shipment: QueuedShipment | DeferredShipment,
  command: Extract<Command, { op: "dispatch" }>,
): Promise<ServiceResponse> {
  if (shipment.state === "deferred" && command.nowMs < shipment.retryAtMs) {
    return { status: 202, body: publicShipment(shipment) };
  }

  let nextProvider: Provider =
    shipment.state === "deferred" ? shipment.nextProvider : "atlas";
  let rejections: readonly Rejection[] =
    shipment.state === "deferred" ? shipment.rejections : [];

  while (!hasPermanentRefusal(rejections, nextProvider)) {
    const outcome = await callCarrier(
      dependencies,
      nextProvider,
      providerRequest(shipment, command.recipient),
      command.nowMs,
    );

    if (outcome.kind === "confirmed") {
      const dispatched: DispatchedShipment = {
        ...baseShipment(shipment),
        state: "dispatched",
        provider: outcome.confirmation.provider,
        bookingId: outcome.confirmation.bookingId,
        dispatchedAtMs: command.nowMs,
      };
      return saveDecision(
        dependencies,
        shipment,
        dispatched,
        {
          shipmentId: shipment.id,
          action: "dispatched",
          provider: dispatched.provider,
        },
        rejections,
      );
    }

    if (outcome.kind === "throttled") {
      const deferred: DeferredShipment = {
        ...baseShipment(shipment),
        state: "deferred",
        nextProvider,
        retryAtMs: outcome.retryAtMs,
        rejections: [...rejections],
      };
      return saveDecision(
        dependencies,
        shipment,
        deferred,
        {
          shipmentId: shipment.id,
          action: "deferred",
          provider: nextProvider,
          retryAtMs: outcome.retryAtMs,
          rejections: [...rejections],
        },
        rejections,
      );
    }

    if (outcome.kind === "aborted") {
      return emitAbort(
        dependencies,
        abortBody(
          shipment.id,
          nextProvider,
          outcome.classification,
          rejections,
        ),
      );
    }

    rejections = [...rejections, outcome.rejection];
    if (nextProvider === "atlas" && !hasPermanentRefusal(rejections, "beacon")) {
      nextProvider = "beacon";
      continue;
    }

    const unavailable: UnavailableShipment = {
      ...baseShipment(shipment),
      state: "unavailable",
      rejections: [...rejections],
    };
    return saveDecision(
      dependencies,
      shipment,
      unavailable,
      {
        shipmentId: shipment.id,
        action: "unavailable",
        rejections: [...rejections],
      },
      rejections,
    );
  }

  const unavailable: UnavailableShipment = {
    ...baseShipment(shipment),
    state: "unavailable",
    rejections: [...rejections],
  };
  return saveDecision(
    dependencies,
    shipment,
    unavailable,
    {
      shipmentId: shipment.id,
      action: "unavailable",
      rejections: [...rejections],
    },
    rejections,
  );
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let storedValue: unknown;
    try {
      storedValue = await dependencies.repository.get(command.shipmentId);
    } catch {
      return emitAbort(
        dependencies,
        abortBody(
          command.shipmentId,
          "repository",
          "repository_failure",
          [],
        ),
      );
    }
    if (storedValue === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseStoredShipment(storedValue);
    if (!shipment) {
      return emitAbort(
        dependencies,
        abortBody(
          command.shipmentId,
          "repository",
          "repository_failure",
          [],
        ),
      );
    }

    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }

    switch (shipment.state) {
      case "queued":
      case "deferred":
        return dispatchShipment(dependencies, shipment, command);
      case "dispatched":
        return { status: 200, body: publicShipment(shipment) };
      case "unavailable":
        return { status: 422, body: publicShipment(shipment) };
    }
  }

  return { handle };
}
